function normalizeEntries(raw) {
  const values = Array.isArray(raw) ? raw : (raw ? [raw] : []);
  const out = [];

  for (const entry of values) {
    try {
      const parsed = typeof entry === 'string' ? JSON.parse(entry) : entry;
      if (Array.isArray(parsed)) {
        for (const sub of parsed) {
          if (sub) out.push(sub);
        }
      } else if (parsed) {
        out.push(parsed);
      }
    } catch {
      // ignore malformed entry
    }
  }

  out.sort((a, b) => {
    const da = new Date(a?.date_time || 0).getTime() || 0;
    const db = new Date(b?.date_time || 0).getTime() || 0;
    return da - db;
  });

  const seen = new Set();
  const deduped = [];
  for (const item of out) {
    const key = String(item?.message_id || '') || `${item?.date_time || ''}__${item?.content_text || ''}`;
    if (seen.has(key)) continue;
    seen.add(key);
    deduped.push(item);
  }

  return deduped;
}

function getNodeJson(name) {
  try {
    return $(name).item.json || {};
  } catch {
    return {};
  }
}

const bufferSource = getNodeJson('Get_Buffer_Data');
const promptSource = getNodeJson('System Promt');
const deduped = normalizeEntries(bufferSource.message);
const textParts = deduped.map((item) => String(item?.content_text || item?.data || '').trim()).filter(Boolean);
const lastItem = deduped.length ? deduped[deduped.length - 1] : null;
const processedMessageIds = deduped.map((item) => String(item?.message_id || '')).filter(Boolean);
const signature = processedMessageIds.length
  ? processedMessageIds.join('|')
  : deduped.map((item) => `${item?.date_time || ''}__${item?.content_text || ''}`).join('|');

return [{
  json: {
    concat_message: textParts.join(' ').replace(/\s+/g, ' ').trim(),
    system_promt: promptSource.aigentss_system_promt || $json.aigentss_system_promt || '',
    buffer_items: deduped,
    buffer_items_count: deduped.length,
    buffer_last_message_id: lastItem?.message_id ? String(lastItem.message_id) : null,
    buffer_last_message_text: lastItem?.data || lastItem?.content_text || null,
    buffer_signature: signature,
    processed_message_ids: processedMessageIds,
  },
}];

const message = items[0].json.body || {};
const content = message.content || '';
const attachments = message.attachments || [];

function makeInternal(url) {
  if (!url) return url;
  const match = String(url).match(/^https:\/\/([a-zA-Z0-9\-]+)\.ocm\.aigentss\.cloud(.*)/);
  if (!match) return url;
  return 'http://' + match[1] + '.ocm.aigentss.cloud:3000' + (match[2] || '');
}

const processedAttachments = attachments.map(att => ({
  ...att,
  data_url_external: att.data_url || null,
  data_url_internal: makeInternal(att.data_url),
  thumb_url_external: att.thumb_url || null,
  thumb_url_internal: makeInternal(att.thumb_url),
}));

let type = 'unknown';
if (attachments.length === 0 && content.trim() !== '') {
  type = 'text';
} else if (attachments.length > 0) {
  if (attachments.every(a => a.file_type === 'image')) {
    type = content.trim() !== '' ? 'image_with_text' : 'image';
  } else if (attachments.every(a => a.file_type === 'audio')) {
    type = 'audio';
  } else if (attachments.every(a => a.file_type === 'location')) {
    type = 'location';
  } else {
    type = 'mixed';
  }
}

return [{
  json: {
    type,
    content_text: content,
    attachments: processedAttachments,
    raw: items[0].json,
  },
}];

const node = items[0].json;
const editFields = $('Edit Fields').item.json;

// Extraer coordenadas del attachment
const attachment = node.attachments?.[0] || {};
const lat = attachment.coordinates_lat || null;
const lon = attachment.coordinates_long || null;

// Construir el content_text para el siguiente nodo
//const content = {
//  lat,
//  lon
//};
const content = `${lat}, ${lon}`;

let result = {
  type: node.type,
  content: content,   // aquí va listo para el agente
  raw: editFields
};

return [{ json: result }];

const out = [];

for (const item of $input.all()) {
  const type = item.json.type;

  if (type === "text" || type === "image_with_text") {
    out.push({
      json: {
        content: item.json.content_text,
        type: "text"
      }
    });
  } else {
    out.push(item);
  }
}

return out;

const node = items[0].json;
const editFields = $('Edit Fields').item.json;

let result = {
  type: node.type,
  content_text: node.content,
  raw: editFields

};

return [{ json: result }];

function nodeJson(name) {
  try {
    return $(name).item.json || {};
  } catch {
    return {};
  }
}

const source = $json.output?.messages || nodeJson('Semantic Response AI Aigent').output?.messages || [];

if (Array.isArray(source) && source.length > 0) {
  return source.map((m, i) => ({
    indx: i,
    sms: m.sms || '',
    url: m.url || '',
    hasUrl: Boolean(m.url && m.url.trim() !== '')
  }));
}

const prep = nodeJson('Prepare Channel Delivery');
const principalReply = nodeJson('Principal AI Agentss 2.2 - WhatsApp Interactive').output?.reply || nodeJson('Principal AI Aigent  2.2').output?.reply || {};
const replyText = String(prep.delivery_text || principalReply.text || '').trim();
const attachments = (Array.isArray(prep.delivery_attachments) && prep.delivery_attachments.length)
  ? prep.delivery_attachments
  : (Array.isArray(principalReply.channel_hints?.attachments) ? principalReply.channel_hints.attachments : []);

if (attachments.length > 0) {
  return attachments.map((attachment, i) => ({
    json: {
      indx: i,
      sms: i === 0 ? replyText : '',
      url: String(attachment?.url || '').trim(),
      hasUrl: Boolean(String(attachment?.url || '').trim())
    }
  }));
}

if (replyText) {
  return [{
    json: {
      indx: 0,
      sms: replyText,
      url: '',
      hasUrl: false
    }
  }];
}

return [];

const event = String($json.body?.event || '').toLowerCase();
const messageType = String($json.body?.message_type || '').toLowerCase();
const isPrivate = Boolean($json.body?.private);

const currentMessage = $json.body?.conversation?.messages?.find(
  msg => String(msg?.id) === String($json.body?.id)
) || {};

const sender = $json.body?.sender || currentMessage.sender || {};
const senderType = String(currentMessage.sender_type || '').toLowerCase();
const senderName = String(sender.name || currentMessage.sender?.name || '').toLowerCase();
const senderEmail = String(sender.email || currentMessage.sender?.email || '').toLowerCase();
const content = String(
  $json.body?.content ??
  currentMessage.content ??
  currentMessage.processed_message_content ??
  ''
).trim();

const isAutomationSender =
  senderName.includes('aigents') ||
  senderEmail.includes('aigentss.com');

const isIncomingUserMessage =
  event === 'message_created' &&
  messageType === 'incoming' &&
  !isPrivate &&
  senderType === 'contact';

const isPublicHumanTakeoverMessage =
  event === 'message_created' &&
  messageType === 'outgoing' &&
  !isPrivate &&
  senderType === 'user' &&
  content.length > 0 &&
  !isAutomationSender;

const shouldContinue = isIncomingUserMessage || isPublicHumanTakeoverMessage;

return [{
  json: {
    ...$json,
    is_user_message: shouldContinue,
    _debug: {
      event,
      message_type: messageType,
      sender_type: senderType,
      private: isPrivate,
      matched_message_id: currentMessage.id || null,
      content_present: content.length > 0,
      automation_sender: isAutomationSender,
      incoming_user_message: isIncomingUserMessage,
      public_human_takeover_message: isPublicHumanTakeoverMessage,
    },
  },
}];

const source = Array.isArray($json.messages) ? $json.messages : (Array.isArray($json.payload) ? $json.payload : []);
const publicMessages = source.filter(message => !Boolean(message?.private));
publicMessages.sort((a, b) => {
  const timeDiff = (Number(a?.created_at) || 0) - (Number(b?.created_at) || 0);
  if (timeDiff !== 0) return timeDiff;
  return (Number(a?.id) || 0) - (Number(b?.id) || 0);
});
function roleFor(message) {
  const senderType = String(message?.sender_type || message?.sender?.type || '').toLowerCase();
  if (senderType === 'contact') return 'cliente';
  if (senderType === 'user') return 'agente';
  if (senderType === 'agentbot' || senderType === 'captain::assistant') return 'bot';
  const messageType = Number(message?.message_type);
  if (messageType === 0) return 'cliente';
  if (messageType === 1) return 'agente';
  return 'sistema';
}
function textFor(message) {
  const content = String(message?.content || message?.processed_message_content || '').trim();
  if (content) return content;
  const attachments = Array.isArray(message?.attachments) ? message.attachments : (message?.attachment ? [message.attachment] : []);
  if (attachments.length > 0) {
    const types = [...new Set(attachments.map(item => String(item?.file_type || 'archivo').trim()).filter(Boolean))];
    return `[adjunto:${types.join(',') || 'archivo'}]`;
  }
  const contentType = String(message?.content_type || '').trim();
  if (contentType && contentType !== 'text') return `[${contentType}]`;
  return '[sin contenido]';
}
const normalized = publicMessages.map(message => `${roleFor(message)}: ${textFor(message)}`);
const limited = normalized.slice(-120);
return [{ json: { conversation_history_text: limited.join('\n'), conversation_message_count: publicMessages.length, conversation_history_truncated: publicMessages.length > limited.length } }];

