const latestMessage = String($('Set Contact Context').item.json.concat_message || '').trim();
const normalized = latestMessage.toLowerCase();
const contentAttributes = $('Webhook').item.json.body?.content_attributes || {};
const publicMessageCount = Number($('Format Conversation History').item.json.conversation_message_count || 0);
const state = $('Set Contact Context').item.json.mcp_booking_state || {};
const contact = $('Set Contact Context').item.json.contact_context || {};
const firstInteraction = publicMessageCount <= 1;
const explicitEntrySource = contentAttributes?.meta?.entry_source || contentAttributes?.entry_source || null;
const models = [
  'kia picanto',
  'picanto',
  'kia soluto',
  'soluto',
  'kia sonet',
  'sonet',
  'kia seltos',
  'seltos',
  'kia sportage',
  'sportage',
  'kia sorento',
  'sorento',
  'kia carnival',
  'carnival',
  'kia tasman',
  'tasman'
];
const matched = models.filter(model => normalized.includes(model));
const uniqueMatches = [...new Set(matched)];
let entrySource = state.entry_source || null;
let entrySourceConfidence = state.entry_source_confidence || null;
if (!entrySource && firstInteraction) {
  if (explicitEntrySource) {
    entrySource = String(explicitEntrySource);
    entrySourceConfidence = 'high';
  } else if (uniqueMatches.length === 1 && normalized.split(/\s+/).filter(Boolean).length <= 6) {
    entrySource = 'cta_meta_inferred';
    entrySourceConfidence = 'medium';
  } else {
    entrySource = 'direct_message';
    entrySourceConfidence = 'low';
  }
}
const entryModelHint = state.entry_model_hint || (uniqueMatches.length === 1 ? uniqueMatches[0] : null);
const selectedModel = state.selected_model || state.latest_selected_model || entryModelHint || null;
const selectedModelId = state.selected_model_id || state.latest_selected_model_id || null;
const selectedEstablishmentId = state.selected_establishment_id || null;
const selectedEstablishmentName = state.selected_establishment_name || null;
const selectedCity = state.selected_city || null;
const purchaseTimeframeDays = Number(state.purchase_timeframe_days ?? NaN);
let temperatureLabel = state.temperature_label || null;
if (!temperatureLabel && Number.isFinite(purchaseTimeframeDays)) {
  if (purchaseTimeframeDays <= 7) temperatureLabel = 'hot_a';
  else if (purchaseTimeframeDays <= 15) temperatureLabel = 'hot_b';
  else if (purchaseTimeframeDays <= 30) temperatureLabel = 'hot_c';
  else if (purchaseTimeframeDays <= 90) temperatureLabel = 'warm';
  else temperatureLabel = 'cold';
}
const temperatureBucket = temperatureLabel ? (['hot_a','hot_b','hot_c','warm'].includes(temperatureLabel) ? 'hot_or_warm' : 'cold') : null;
const bookingPersonalDataComplete = Boolean((state.customer_name || contact.name) && (state.customer_email || contact.email) && (state.customer_identifier || contact.identifier) && (state.customer_phone || contact.phone_number) && selectedCity);
const journeyType = String(entrySource || '').startsWith('cta') && entryModelHint ? 'cta_model_first' : 'organic_catalog_first';
let journeyStep = 'conversation_support';
if (!bookingPersonalDataComplete) journeyStep = 'collect_profile';
else if (!selectedModel) journeyStep = journeyType === 'organic_catalog_first' ? 'show_catalog' : 'confirm_cta_model';
else if (!Number.isFinite(purchaseTimeframeDays)) journeyStep = 'collect_purchase_timeframe';
else if (!selectedEstablishmentId) journeyStep = 'resolve_establishment';
else if (!state.active_appointment_id) journeyStep = 'offer_appointment';
return [{ json: {
  first_interaction: firstInteraction,
  entry_source_check_needed: firstInteraction && !state.entry_source,
  entry_source: entrySource,
  entry_source_confidence: entrySourceConfidence,
  entry_model_hint: entryModelHint,
  entry_model_id_hint: selectedModelId,
  journey_type: journeyType,
  journey_step: journeyStep,
  selected_model_id: selectedModelId,
  selected_model: selectedModel,
  selected_establishment_id: selectedEstablishmentId,
  selected_establishment_name: selectedEstablishmentName,
  selected_city: selectedCity,
  booking_personal_data_complete: bookingPersonalDataComplete,
  temperature_label: temperatureLabel,
  temperature_bucket: temperatureBucket,
  should_send_catalog: journeyType === 'organic_catalog_first' && !selectedModel,
  should_send_vehicle_info: Boolean(selectedModel),
  should_collect_profile: !bookingPersonalDataComplete,
  should_collect_purchase_timeframe: !Number.isFinite(purchaseTimeframeDays),
  should_offer_appointment: Boolean(selectedModel && selectedEstablishmentId && Number.isFinite(purchaseTimeframeDays)),
  appointment_offer_status: state.appointment_offer_status || null
} }];

function normalizeEntries(raw) {
  const values = Array.isArray(raw) ? raw : (raw ? [raw] : []);
  const out = [];

  for (const entry of values) {
    try {
      const parsed = typeof entry === 'string' ? JSON.parse(entry) : entry;
      if (Array.isArray(parsed)) {
        for (const sub of parsed) {
          if (sub) out.push(sub);
        }
      } else if (parsed) {
        out.push(parsed);
      }
    } catch {}
  }

  out.sort((a, b) => {
    const da = new Date(a?.date_time || 0).getTime() || 0;
    const db = new Date(b?.date_time || 0).getTime() || 0;
    return da - db;
  });

  const deduped = [];
  const seen = new Set();
  for (const item of out) {
    const key = String(item?.message_id || '') || `${item?.date_time || ''}__${item?.content_text || ''}`;
    if (seen.has(key)) continue;
    seen.add(key);
    deduped.push(item);
  }

  return deduped;
}

const deduped = normalizeEntries($json.message);
const ids = deduped.map((item) => String(item?.message_id || '')).filter(Boolean);
const signature = ids.length
  ? ids.join('|')
  : deduped.map((item) => `${item?.date_time || ''}__${item?.content_text || ''}`).join('|');

return [{
  json: {
    current_buffer_items: deduped,
    current_buffer_signature: signature,
    current_buffer_last_text: deduped.length ? (deduped[deduped.length - 1].data || deduped[deduped.length - 1].content_text || null) : null,
    current_buffer_last_message_id: deduped.length ? String(deduped[deduped.length - 1].message_id || '') : '',
  },
}];

function getNodeReply(name) {
  try {
    return $(name).item.json.output?.reply || null;
  } catch {
    return null;
  }
}

const reply = $json.output?.reply
  || getNodeReply('Principal AI Agentss 2.2 - WhatsApp Interactive')
  || getNodeReply('Principal AI Aigent  2.2')
  || {};
const hints = reply.channel_hints || {};
const supportsMeta = Boolean($json.supports_meta_interactive);
const channelFamily = String($json.channel_family || 'generic');
const attachments = Array.isArray($json.delivery_attachments) ? $json.delivery_attachments : (Array.isArray(hints.attachments) ? hints.attachments : []);
const fallbackText = String($json.delivery_text || hints.fallback_text || reply.text || '').trim();
const preMetaText = String($json.delivery_text || hints.pre_meta_text || reply.text || '').trim();
const privateNoteSummary = String($json.private_note_content || hints.private_note_summary || '').trim();
const interactiveType = String($json.interactive_type || '').trim();
const conversation = $('Webhook').item.json.body?.conversation || {};
const account = $('Webhook').item.json.body?.account || {};
const recipient = String(conversation?.meta?.sender?.phone_number || conversation?.contact_inbox?.source_id || $('Webhook').item.json.body?.source_id || '').replace(/[^0-9]/g, '');
let route = String($json.delivery_route || '').trim() || 'chat_text';
let metaRequestBody = $json.meta_request_body || null;
let metaParseError = null;
if (metaRequestBody && typeof metaRequestBody === 'object') {
  metaRequestBody.messaging_product = 'whatsapp';
  if (!metaRequestBody.to && recipient) metaRequestBody.to = recipient;
} else if (supportsMeta && String(hints.preferred_delivery || '').trim() === 'meta_interactive') {
  const interactive = hints.meta_interactive || {};
  const metaRequestBodyJson = String(interactive.meta_request_body_json || '').trim();
  if (metaRequestBodyJson) {
    try {
      metaRequestBody = JSON.parse(metaRequestBodyJson);
      if (metaRequestBody && typeof metaRequestBody === 'object') {
        metaRequestBody.messaging_product = 'whatsapp';
        if (!metaRequestBody.to && recipient) metaRequestBody.to = recipient;
        route = 'meta_interactive';
      }
    } catch (error) {
      metaParseError = error.message;
    }
  }
}
if (!supportsMeta) route = 'chat_text';
const noteContent = privateNoteSummary || (route === 'meta_interactive' ? `Respuesta interactiva enviada por Meta (${interactiveType || 'interactive'}).` : '');
return [{ json: { ...$json, delivery_route: route, delivery_text: route === 'meta_interactive' ? preMetaText : fallbackText, delivery_attachments: attachments, supports_meta_interactive: supportsMeta, channel_family: channelFamily, meta_interactive_type: interactiveType || 'none', meta_request_body: metaRequestBody, meta_parse_error: metaParseError, private_note_content: noteContent, should_create_private_note: route === 'meta_interactive' && noteContent !== '', conversation_id: conversation.id, account_id: account.id, recipient_wa_id: recipient } }];

